// OFFLINE Windows DPAPI only. No Docker or network command. Never logs raw errors/key/payload.
import fs from 'node:fs';import assert from 'node:assert/strict';import {spawnSync} from 'node:child_process';import {unseal,validateContents} from './bundle.mjs';import {sha} from './filesystem.mjs';
import {archiveMetadata} from './filesystem.mjs';import {RequestCodec,assertIssuedRequest} from './request-codec.mjs';import {ProposedNativeAdapter} from './native-adapter.proposed.mjs';
const dir='docs/estadisticas-v1/p04-t01c-executor-audit-20261016/';let key;
try{const pins=JSON.parse(fs.readFileSync(dir+'pins.json'));for(const f of pins.referenceFiles)assert.equal(sha(fs.readFileSync(f.path)),f.sha256);assert.ok(pins.bundle.path.startsWith('supabase/statistics-v1-test/.runtime/loopback-bundles/'));const bytes=fs.readFileSync(pins.bundle.path);assert.equal(sha(bytes),pins.bundle.sha256);const e=JSON.parse(bytes);
 const command="Add-Type -AssemblyName System.Security; $v=[Convert]::FromBase64String([Console]::In.ReadToEnd()); [Convert]::ToBase64String([Security.Cryptography.ProtectedData]::Unprotect($v,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser))";
 const r=spawnSync('powershell.exe',['-NoLogo','-NoProfile','-NonInteractive','-Command',command],{encoding:'utf8',input:e.protectedKey,windowsHide:true,timeout:15000});assert.equal(r.status,0);key=Buffer.from(r.stdout.trim(),'base64');const data=unseal(bytes,key,pins);const result=validateContents(data,pins);
 const sources=Object.fromEntries(data.targets.map(t=>[t.kind,t.originalInspect]));const files=Object.fromEntries(data.targets.map(t=>[t.kind,t.archives.map(a=>{const meta=archiveMetadata(Buffer.from(a.tarBase64,'base64'));return {path:a.path,uid:meta.uid,gid:meta.gid,mode:meta.mode&0o7777,mtime:meta.mtime,contentHash:meta.contentSha256,archiveHash:a.sha256};})]));const directories=Object.fromEntries(data.targets.map(t=>[t.kind,t.directoryMetadata.map(x=>({path:x.path,uid:x.uid,gid:x.gid,mode:parseInt(x.mode,8)}))]));
 const codec=new RequestCodec({sources,files,directories,runId:pins.runId,existingIds:[...pins.targets.map(x=>x.id),...pins.others.map(x=>x.id)],authority:'APPROVED_CANDIDATE'});const qualified=[];
 for(const kind of ['db','kong']){const req=codec.request('create',kind);assertIssuedRequest(req,{allowSimulation:false});assert.equal(req.bodyHash,pins.targets.find(x=>x.kind===kind).payloadSha256);let denied=false;try{await new ProposedNativeAdapter().send(req);}catch(error){denied=error.message==='NATIVE_ENGINE_HARD_LOCKED_REQUIRES_NEW_REVIEWED_BUILD';}assert.equal(denied,true);qualified.push({kind,payloadSha256:req.bodyHash,nativeHardBarrierConfirmed:true});}
 fs.writeFileSync(dir+'private-bundle-audit.json',JSON.stringify({at:new Date().toISOString(),...result,bundleSha256:pins.bundle.sha256,qualifiedCandidateDescriptors:qualified,directoryMtimeWitness:'PENDING_FRESH_STOPPED_EXPORT; no timestamp fabricated',newExistingIdInventory:'Historical five only; fresh global negative-sharing inventory required before intervention'},null,2)+'\n');console.log(JSON.stringify({result:result.result,archives:result.targets.reduce((s,x)=>s+x.archivesValidated,0),qualifiedCandidateDescriptors:qualified.length,engineRequests:0}));
}catch{console.log('BLOCKED_OFFLINE_PRIVATE_AUDIT; sensitive error suppressed');process.exitCode=1;}finally{key?.fill(0);}
